const target = $('Define Mapping Target').first().json;
const emaRun = $('Lookup EMA Run').first().json;
const tcmRun = $('Lookup TCM Run').first().json;

// --------------------------------------------------
// 1. Basic checks
// --------------------------------------------------

if (!emaRun) {
  throw new Error('EMA run is missing.');
}

if (!tcmRun) {
  throw new Error('TCM run is missing.');
}

if (!emaRun.profile_json) {
  throw new Error('EMA profile_json is missing.');
}

if (!tcmRun.profile_json) {
  throw new Error('TCM profile_json is missing.');
}

// --------------------------------------------------
// 2. Parse profile_json safely
// --------------------------------------------------

function parseProfile(value, label) {
  if (value === null || value === undefined) {
    throw new Error(`${label} profile_json is empty.`);
  }

  if (typeof value === 'object') {
    return value;
  }

  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch (error) {
      throw new Error(
        `${label} profile_json could not be parsed: ${error.message}`
      );
    }
  }

  throw new Error(
    `${label} profile_json has unexpected type: ${typeof value}`
  );
}

const ema = parseProfile(
  emaRun.profile_json,
  'EMA'
);

const tcm = parseProfile(
  tcmRun.profile_json,
  'TCM'
);

// --------------------------------------------------
// 3. Validate source runs
// --------------------------------------------------

if (emaRun.validation_status !== 'pass') {
  throw new Error(
    `EMA extraction is not validated: ${emaRun.validation_status}`
  );
}

if (tcmRun.validation_status !== 'pass') {
  throw new Error(
    `TCM extraction is not validated: ${tcmRun.validation_status}`
  );
}

// --------------------------------------------------
// 4. Read indications robustly
// --------------------------------------------------

const europeanIndications =
  ema.medicinal_use?.indications ??
  ema.extracted_data?.medicinal_use?.indications ??
  [];

const tcmIndications =
  tcm.traditional_indications ??
  tcm.extracted_data?.traditional_indications ??
  [];

// --------------------------------------------------
// 5. Read TCM actions robustly
// --------------------------------------------------

const tcmActions =
  tcm.traditional_actions ??
  tcm.extracted_data?.traditional_actions ??
  [];

// --------------------------------------------------
// 6. Check content
// --------------------------------------------------

if (europeanIndications.length === 0) {
  throw new Error(
    `No European indications found. EMA profile keys: ${Object.keys(ema).join(', ')}`
  );
}

if (tcmIndications.length === 0) {
  throw new Error(
    `No TCM indications found. TCM profile keys: ${Object.keys(tcm).join(', ')}`
  );
}

// --------------------------------------------------
// 7. Determine metadata safely
// --------------------------------------------------

const emaMetadata =
  ema.profile_metadata ??
  ema.extracted_data?.profile_metadata ??
  {};

const tcmMetadata =
  tcm.profile_metadata ??
  tcm.extracted_data?.profile_metadata ??
  {};

const emaMedicinalUse =
  ema.medicinal_use ??
  ema.extracted_data?.medicinal_use ??
  {};

const emaClinical =
  ema.clinical_efficacy ??
  ema.extracted_data?.clinical_efficacy ??
  {};

const tcmIdentity =
  tcm.identity ??
  tcm.extracted_data?.identity ??
  {};

const tcmProperties =
  tcm.tcm_properties ??
  tcm.extracted_data?.tcm_properties ??
  {};

// --------------------------------------------------
// 8. Build clean cross-cultural mapping input
// --------------------------------------------------

return {
  json: {

    mapping_metadata: {
      mapping_version:
        target.mapping_version ??
        'phythera_crosscultural_v1',

      mapping_scope:
        target.mapping_scope ??
        'traditional_indications',

      plant:
        target.plant ??
        emaMetadata.plant ??
        tcmMetadata.plant ??
        null,

      ema_run_id:
        emaRun.id ?? null,

      tcm_run_id:
        tcmRun.id ?? null,

      input_validation:
        'pass'
    },

    european_profile: {

      source_system:
        'European phytotherapy',

      source_type:
        'EMA/HMPC',

      source_title:
        emaMetadata.document_title ??
        null,

      source_id:
        emaMetadata.document_id ??
        null,

      source_url:
        emaMetadata.source_url ??
        null,

      indications:
        europeanIndications.map(
          (item, index) => ({
            indication_id:
              `ema_${index + 1}`,

            source_wording:
              item.source_wording ??
              null,

            source_quote:
              item.source_quote ??
              null,

            regulatory_basis:
              item.regulatory_basis ??
              null
          })
        ),

      regulatory_context: {

        traditional_use_status:
          emaMedicinalUse
            .traditional_use_status ??
          null,

        well_established_use_status:
          emaMedicinalUse
            .well_established_use_status ??
          null,

        duration_of_use:
          emaMedicinalUse
            .duration_of_use ??
          null
      },

      clinical_context: {

        evidence_summary:
          emaClinical
            .evidence_summary ??
          null,

        overall_efficacy_conclusion:
          emaClinical
            .overall_efficacy_conclusion ??
          null,

        well_established_use_supported:
          emaClinical
            .well_established_use_supported ??
          null
      }
    },

    tcm_profile: {

      source_system:
        'Traditional Chinese Medicine',

      source_type:
        tcmMetadata.source_type ??
        'herbal_database',

      source_name:
        tcmMetadata.source_name ??
        null,

      source_url:
        tcmMetadata.source_url ??
        null,

      chinese_name:
        tcmMetadata.chinese_name ??
        null,

      pinyin:
        tcmMetadata.pinyin ??
        null,

      medicinal_group:
        tcmIdentity.medicinal_group ??
        null,

      tcm_properties: {

        nature:
          tcmProperties.nature ??
          null,

        flavors:
          tcmProperties.flavors ??
          [],

        meridian_affinity:
          tcmProperties
            .meridian_affinity ??
          []
      },

      traditional_actions:
        tcmActions.map(
          (item, index) => ({
            action_id:
              `tcm_action_${index + 1}`,

            action:
              item.action ??
              null,

            source_quote:
              item.source_quote ??
              null
          })
        ),

      indications:
        tcmIndications.map(
          (item, index) => ({
            indication_id:
              `tcm_${index + 1}`,

            source_wording:
              item.source_wording ??
              null,

            source_quote:
              item.source_quote ??
              null
          })
        )
    },

    input_counts: {

      european_indications:
        europeanIndications.length,

      tcm_indications:
        tcmIndications.length,

      tcm_actions:
        tcmActions.length
    }
  }
};

const input = $input.first().json;

const europeanIndications =
  input.european_profile?.indications ?? [];

const tcmIndications =
  input.tcm_profile?.indications ?? [];

// --------------------------------------------------
// 1. Safety checks
// --------------------------------------------------

if (europeanIndications.length === 0) {
  throw new Error(
    'No European indications available for mapping.'
  );
}

if (tcmIndications.length === 0) {
  throw new Error(
    'No TCM indications available for mapping.'
  );
}

// --------------------------------------------------
// 2. Define allowed mapping categories
// --------------------------------------------------

const allowedCategories = [
  'strong_overlap',
  'partial_overlap',
  'distinct_concepts',
  'no_meaningful_mapping'
];

// --------------------------------------------------
// 3. Rules for semantic mapping
// --------------------------------------------------

const mappingRules = [
  'Compare only the meaning of the two source indications.',
  'Do not infer clinical efficacy.',
  'Do not infer that cross-cultural similarity proves therapeutic effectiveness.',
  'Do not reinterpret TCM terminology as biomedical terminology unless the source wording itself explicitly supports that interpretation.',
  'Preserve the distinction between traditional use and established clinical evidence.',
  'Use strong_overlap only when the two descriptions substantially refer to the same symptom or use concept.',
  'Use partial_overlap when the concepts share a meaningful component but differ in scope, context, severity, or traditional framing.',
  'Use distinct_concepts when both are understandable concepts but describe substantially different uses.',
  'Use no_meaningful_mapping when there is no defensible semantic relationship between the two uses.',
  'Base the assessment only on the supplied wording.'
];

// --------------------------------------------------
// 4. Create all European × TCM comparison pairs
// --------------------------------------------------

const tasks = [];

for (const european of europeanIndications) {

  for (const tcm of tcmIndications) {

    tasks.push({
      mapping_metadata: {
        mapping_version:
          input.mapping_metadata?.mapping_version ??
          'phythera_crosscultural_v1',

        mapping_scope:
          input.mapping_metadata?.mapping_scope ??
          'traditional_indications',

        plant:
          input.mapping_metadata?.plant ??
          null,

        ema_run_id:
          input.mapping_metadata?.ema_run_id ??
          null,

        tcm_run_id:
          input.mapping_metadata?.tcm_run_id ??
          null,

        pair_id:
          `${european.indication_id}__${tcm.indication_id}`
      },

      european_indication: {
        indication_id:
          european.indication_id,

        source_system:
          input.european_profile?.source_system ??
          'European phytotherapy',

        source_type:
          input.european_profile?.source_type ??
          'EMA/HMPC',

        source_wording:
          european.source_wording ??
          null,

        source_quote:
          european.source_quote ??
          null,

        regulatory_basis:
          european.regulatory_basis ??
          null
      },

      tcm_indication: {
        indication_id:
          tcm.indication_id,

        source_system:
          input.tcm_profile?.source_system ??
          'Traditional Chinese Medicine',

        source_name:
          input.tcm_profile?.source_name ??
          null,

        chinese_name:
          input.tcm_profile?.chinese_name ??
          null,

        pinyin:
          input.tcm_profile?.pinyin ??
          null,

        source_wording:
          tcm.source_wording ??
          null,

        source_quote:
          tcm.source_quote ??
          null
      },

      mapping_config: {
        allowed_categories:
          allowedCategories,

        rules:
          mappingRules
      }
    });
  }
}

// --------------------------------------------------
// 5. Return one n8n item per comparison
// --------------------------------------------------

return tasks.map(task => ({
  json: task
}));

const input = $json;

const targetSchema = {
  pair_id: null,

  mapping_category: null,

  semantic_overlap: null,

  key_difference: null,

  confidence: null,

  convergence_claim: null,

  mapping_basis: {
    european_concept: null,
    tcm_concept: null,
    shared_concept: null
  },

  uncertainties: []
};

const rules = [
  'Compare only the semantic meaning of the supplied European and TCM indication wording.',
  'Do not assess clinical efficacy.',
  'Do not infer that semantic similarity proves therapeutic effectiveness.',
  'Do not introduce biomedical interpretations that are not explicitly present in the supplied wording.',
  'Preserve the distinction between traditional medical concepts and modern biomedical concepts.',
  'Use strong_overlap only when both indications substantially describe the same symptom or use concept.',
  'Use partial_overlap when there is a meaningful shared concept but the indications differ in scope, context, severity, or framing.',
  'Use distinct_concepts when both indications are understandable but describe substantially different therapeutic or symptom concepts.',
  'Use no_meaningful_mapping only when no defensible semantic relationship can be identified.',
  'Confidence must be between 0 and 1.',
  'Be conservative. When uncertain between two categories, choose the weaker overlap category.',
  'Do not use outside knowledge.'
];

return {
  json: {
    mapping_metadata:
      input.mapping_metadata,

    european_indication:
      input.european_indication,

    tcm_indication:
      input.tcm_indication,

    mapping_config: {
      allowed_categories:
        input.mapping_config?.allowed_categories ?? [
          'strong_overlap',
          'partial_overlap',
          'distinct_concepts',
          'no_meaningful_mapping'
        ],

      rules,

      target_schema:
        targetSchema
    }
  }
};

const context = $('Define Mapping Output Schema').item.json;

const errors = [];
const warnings = [];

// --------------------------------------------------
// 1. Clean possible Markdown fences
// --------------------------------------------------

function cleanJsonString(value) {
  return String(value ?? '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

// --------------------------------------------------
// 2. Parse AI output
// --------------------------------------------------

let mappedData = null;

try {
  mappedData = JSON.parse(
    cleanJsonString($json.text)
  );
} catch (error) {
  errors.push({
    type: 'json_parse_error',
    path: '$',
    message: error.message
  });
}

// --------------------------------------------------
// 3. Generic schema validation
// --------------------------------------------------

function validateStructure(schema, value, path = '$') {

  if (Array.isArray(schema)) {

    if (!Array.isArray(value)) {
      errors.push({
        type: 'type_mismatch',
        path,
        message: 'Expected array.'
      });

      return;
    }

    if (schema.length > 0) {
      value.forEach((child, index) => {
        validateStructure(
          schema[0],
          child,
          `${path}[${index}]`
        );
      });
    }

    return;
  }

  if (
    schema !== null &&
    typeof schema === 'object'
  ) {

    if (
      value === null ||
      typeof value !== 'object' ||
      Array.isArray(value)
    ) {
      errors.push({
        type: 'type_mismatch',
        path,
        message: 'Expected object.'
      });

      return;
    }

    const schemaKeys =
      Object.keys(schema);

    const valueKeys =
      Object.keys(value);

    for (const key of schemaKeys) {

      if (!(key in value)) {

        errors.push({
          type: 'missing_key',
          path: `${path}.${key}`,
          message:
            `Missing required key: ${key}`
        });

      } else {

        validateStructure(
          schema[key],
          value[key],
          `${path}.${key}`
        );
      }
    }

    for (const key of valueKeys) {

      if (!(key in schema)) {

        errors.push({
          type: 'unexpected_key',
          path: `${path}.${key}`,
          message:
            `Unexpected key: ${key}`
        });
      }
    }

    return;
  }

  // null in schema = scalar or null
  if (
    value !== null &&
    typeof value === 'object'
  ) {

    errors.push({
      type: 'type_mismatch',
      path,
      message:
        'Expected scalar value or null.'
    });
  }
}

// --------------------------------------------------
// 4. Mapping-specific validation
// --------------------------------------------------

function validateMapping(data) {

  if (!data) {
    return;
  }

  const expectedPairId =
    context.mapping_metadata?.pair_id;

  // Pair ID must match input exactly
  if (data.pair_id !== expectedPairId) {

    errors.push({
      type: 'pair_id_mismatch',
      path: '$.pair_id',
      message:
        `Expected ${expectedPairId}, received ${data.pair_id}.`
    });
  }

  // Allowed categories
  const allowedCategories =
    context.mapping_config
      ?.allowed_categories ?? [];

  if (
    !allowedCategories.includes(
      data.mapping_category
    )
  ) {

    errors.push({
      type: 'invalid_mapping_category',
      path: '$.mapping_category',
      message:
        `Invalid mapping category: ${data.mapping_category}`
    });
  }

  // Confidence
  if (
    typeof data.confidence !== 'number' ||
    data.confidence < 0 ||
    data.confidence > 1
  ) {

    errors.push({
      type: 'invalid_confidence',
      path: '$.confidence',
      message:
        'Confidence must be a number between 0 and 1.'
    });
  }

  // Allowed convergence claims
  const allowedClaims = [
    'cross-cultural convergence',
    'possible cross-cultural convergence',
    'cross-cultural divergence',
    'no cross-cultural mapping'
  ];

  if (
    !allowedClaims.includes(
      data.convergence_claim
    )
  ) {

    errors.push({
      type: 'invalid_convergence_claim',
      path: '$.convergence_claim',
      message:
        `Invalid convergence claim: ${data.convergence_claim}`
    });
  }

  // --------------------------------------------------
  // 5. Logical consistency rules
  // --------------------------------------------------

  const category =
    data.mapping_category;

  const claim =
    data.convergence_claim;

  const sharedConcept =
    data.mapping_basis?.shared_concept;

  const semanticOverlap =
    data.semantic_overlap;

  // Strong overlap
  if (category === 'strong_overlap') {

    if (
      claim !== 'cross-cultural convergence'
    ) {
      errors.push({
        type: 'inconsistent_mapping',
        path: '$.convergence_claim',
        message:
          'strong_overlap requires cross-cultural convergence.'
      });
    }

    if (!sharedConcept) {
      errors.push({
        type: 'missing_shared_concept',
        path:
          '$.mapping_basis.shared_concept',
        message:
          'strong_overlap requires a shared concept.'
      });
    }

    if (!semanticOverlap) {
      errors.push({
        type: 'missing_semantic_overlap',
        path: '$.semantic_overlap',
        message:
          'strong_overlap requires semantic_overlap.'
      });
    }
  }

  // Partial overlap
  if (category === 'partial_overlap') {

    if (
      claim !==
      'possible cross-cultural convergence'
    ) {
      errors.push({
        type: 'inconsistent_mapping',
        path: '$.convergence_claim',
        message:
          'partial_overlap requires possible cross-cultural convergence.'
      });
    }

    if (!sharedConcept) {
      errors.push({
        type: 'missing_shared_concept',
        path:
          '$.mapping_basis.shared_concept',
        message:
          'partial_overlap requires a shared concept.'
      });
    }

    if (!semanticOverlap) {
      errors.push({
        type: 'missing_semantic_overlap',
        path: '$.semantic_overlap',
        message:
          'partial_overlap requires semantic_overlap.'
      });
    }
  }

  // Distinct concepts
  if (category === 'distinct_concepts') {

    if (
      claim !==
      'cross-cultural divergence'
    ) {
      errors.push({
        type: 'inconsistent_mapping',
        path: '$.convergence_claim',
        message:
          'distinct_concepts requires cross-cultural divergence.'
      });
    }

    if (sharedConcept !== null) {
      errors.push({
        type: 'unexpected_shared_concept',
        path:
          '$.mapping_basis.shared_concept',
        message:
          'distinct_concepts should have shared_concept = null.'
      });
    }

    if (semanticOverlap !== null) {
      warnings.push({
        type: 'unexpected_semantic_overlap',
        path: '$.semantic_overlap',
        message:
          'distinct_concepts normally should have semantic_overlap = null.'
      });
    }
  }

  // No meaningful mapping
  if (
    category ===
    'no_meaningful_mapping'
  ) {

    if (
      claim !==
      'no cross-cultural mapping'
    ) {
      errors.push({
        type: 'inconsistent_mapping',
        path: '$.convergence_claim',
        message:
          'no_meaningful_mapping requires no cross-cultural mapping.'
      });
    }

    if (sharedConcept !== null) {
      errors.push({
        type: 'unexpected_shared_concept',
        path:
          '$.mapping_basis.shared_concept',
        message:
          'no_meaningful_mapping requires shared_concept = null.'
      });
    }

    if (semanticOverlap !== null) {
      warnings.push({
        type: 'unexpected_semantic_overlap',
        path: '$.semantic_overlap',
        message:
          'no_meaningful_mapping normally should have semantic_overlap = null.'
      });
    }
  }

  // --------------------------------------------------
  // 6. Uncertainties should be strings
  // --------------------------------------------------

  if (Array.isArray(data.uncertainties)) {

    data.uncertainties.forEach(
      (item, index) => {

        if (typeof item !== 'string') {

          errors.push({
            type:
              'invalid_uncertainty_type',

            path:
              `$.uncertainties[${index}]`,

            message:
              'Each uncertainty must be a string.'
          });
        }
      }
    );
  }
}

// --------------------------------------------------
// 7. Execute validation
// --------------------------------------------------

if (mappedData !== null) {

  validateStructure(
    context.mapping_config.target_schema,
    mappedData
  );

  validateMapping(
    mappedData
  );
}

// --------------------------------------------------
// 8. Determine final status
// --------------------------------------------------

let status = 'pass';

if (errors.length > 0) {

  status = 'fail';

} else if (warnings.length > 0) {

  status = 'warning';
}

// --------------------------------------------------
// 9. Output
// --------------------------------------------------

return {
  json: {

    mapping_metadata:
      context.mapping_metadata,

    european_indication:
      context.european_indication,

    tcm_indication:
      context.tcm_indication,

    schema_version:
      context.mapping_metadata
        ?.mapping_version ??
      'phythera_crosscultural_v1',

    validation: {
      status,
      error_count:
        errors.length,

      warning_count:
        warnings.length,

      errors,
      warnings
    },

    mapped_data:
      mappedData
  }
};

const items = $input.all();

const sourceInput =
  $('Prepare Mapping Input').first().json;


// ============================================================
// 1. Collect mapping results
// ============================================================

const allResults =
  items.map(item => item.json);

if (allResults.length === 0) {
  throw new Error(
    'No mapping results received.'
  );
}


// ============================================================
// 2. Separate usable and failed mappings
// ============================================================

const failedMappings =
  allResults.filter(
    item =>
      item.validation?.status === 'fail'
  );

const usableMappings =
  allResults.filter(
    item =>
      ['pass', 'warning'].includes(
        item.validation?.status
      ) &&
      item.mapped_data
  );


// Do not continue if EVERYTHING failed
if (usableMappings.length === 0) {
  throw new Error(
    `All ${allResults.length} mapping result(s) failed validation.`
  );
}


// ============================================================
// 3. Extract clean validated mapping records
// ============================================================

const cleanMappings =
  usableMappings.map(item => ({

    pair_id:
      item.mapped_data.pair_id,

    mapping_category:
      item.mapped_data.mapping_category,

    confidence:
      item.mapped_data.confidence,

    convergence_claim:
      item.mapped_data.convergence_claim,

    semantic_overlap:
      item.mapped_data.semantic_overlap,

    key_difference:
      item.mapped_data.key_difference,

    mapping_basis:
      item.mapped_data.mapping_basis,

    uncertainties:
      item.mapped_data.uncertainties ?? [],

    european_indication: {
      indication_id:
        item.european_indication.indication_id,

      source_wording:
        item.european_indication.source_wording,

      regulatory_basis:
        item.european_indication.regulatory_basis
    },

    tcm_indication: {
      indication_id:
        item.tcm_indication.indication_id,

      source_wording:
        item.tcm_indication.source_wording
    },

    validation_status:
      item.validation.status
  }));


// ============================================================
// 4. Preserve failed mapping diagnostics
// ============================================================

const failedMappingDiagnostics =
  failedMappings.map(item => ({

    pair_id:
      item.mapping_metadata?.pair_id ??
      null,

    european_indication:
      item.european_indication
        ?.source_wording ?? null,

    tcm_indication:
      item.tcm_indication
        ?.source_wording ?? null,

    errors:
      item.validation?.errors ?? [],

    warnings:
      item.validation?.warnings ?? []
  }));


// ============================================================
// 5. Count categories
// ============================================================

const counts = {
  strong_overlap: 0,
  partial_overlap: 0,
  distinct_concepts: 0,
  no_meaningful_mapping: 0
};

for (const mapping of cleanMappings) {

  if (
    Object.prototype.hasOwnProperty.call(
      counts,
      mapping.mapping_category
    )
  ) {
    counts[mapping.mapping_category]++;
  }
}


// ============================================================
// 6. Identify convergence candidates
// ============================================================

const categoryPriority = {
  strong_overlap: 4,
  partial_overlap: 3,
  distinct_concepts: 2,
  no_meaningful_mapping: 1
};

const convergenceMappings =
  cleanMappings
    .filter(mapping =>
      mapping.mapping_category ===
        'strong_overlap' ||
      mapping.mapping_category ===
        'partial_overlap'
    )
    .sort((a, b) => {

      const categoryDifference =
        categoryPriority[
          b.mapping_category
        ] -
        categoryPriority[
          a.mapping_category
        ];

      if (categoryDifference !== 0) {
        return categoryDifference;
      }

      return (
        Number(b.confidence ?? 0) -
        Number(a.confidence ?? 0)
      );
    });


// ============================================================
// 7. Strongest convergence
// ============================================================

const strongestConvergence =
  convergenceMappings.length > 0
    ? convergenceMappings[0]
    : null;


// ============================================================
// 8. High-level interpretation
// ============================================================

let overallPattern =
  'predominantly_distinct';

if (counts.strong_overlap > 0) {

  overallPattern =
    'cross_cultural_convergence_detected';

} else if (counts.partial_overlap > 0) {

  overallPattern =
    'limited_cross_cultural_convergence';

} else if (
  counts.distinct_concepts === 0 &&
  counts.no_meaningful_mapping > 0
) {

  overallPattern =
    'no_cross_cultural_mapping_detected';
}


// ============================================================
// 9. Overall validation status
// ============================================================

const overallValidationStatus =
  failedMappings.length > 0
    ? 'warning'
    : 'pass';


// ============================================================
// 10. Build final profile
// ============================================================

const profile = {

  profile_metadata: {

    profile_type:
      'cross_cultural_mapping',

    schema_version:
      sourceInput.mapping_metadata
        ?.mapping_version ??
      'phythera_crosscultural_v1',

    plant:
      sourceInput.mapping_metadata
        ?.plant ??
      null,

    ema_run_id:
      sourceInput.mapping_metadata
        ?.ema_run_id ??
      null,

    tcm_run_id:
      sourceInput.mapping_metadata
        ?.tcm_run_id ??
      null,

    mapping_scope:
      sourceInput.mapping_metadata
        ?.mapping_scope ??
      'traditional_indications',

    validation_status:
      overallValidationStatus
  },


  source_context: {

    european: {

      source_system:
        sourceInput.european_profile
          ?.source_system ??
        null,

      source_type:
        sourceInput.european_profile
          ?.source_type ??
        null,

      source_title:
        sourceInput.european_profile
          ?.source_title ??
        null,

      source_id:
        sourceInput.european_profile
          ?.source_id ??
        null,

      source_url:
        sourceInput.european_profile
          ?.source_url ??
        null,

      regulatory_context:
        sourceInput.european_profile
          ?.regulatory_context ??
        {}
    },


    tcm: {

      source_system:
        sourceInput.tcm_profile
          ?.source_system ??
        null,

      source_name:
        sourceInput.tcm_profile
          ?.source_name ??
        null,

      source_url:
        sourceInput.tcm_profile
          ?.source_url ??
        null,

      chinese_name:
        sourceInput.tcm_profile
          ?.chinese_name ??
        null,

      pinyin:
        sourceInput.tcm_profile
          ?.pinyin ??
        null,

      medicinal_group:
        sourceInput.tcm_profile
          ?.medicinal_group ??
        null
    }
  },


  mapping_summary: {

    total_comparisons:
      allResults.length,

    valid_comparisons:
      cleanMappings.length,

    failed_comparisons:
      failedMappings.length,

    category_counts:
      counts,

    convergence_count:
      counts.strong_overlap +
      counts.partial_overlap,

    overall_pattern:
      overallPattern
  },


  strongest_convergence:
    strongestConvergence,

  convergence_candidates:
    convergenceMappings,

  mappings:
    cleanMappings,

  failed_mappings:
    failedMappingDiagnostics,


  interpretation_guardrails: [
    'Semantic convergence does not demonstrate clinical efficacy.',
    'Traditional-use concepts are preserved in their source-specific context.',
    'Cross-cultural mapping is based on supplied source wording only.',
    'Clinical evidence must be evaluated separately from semantic convergence.'
  ]
};


return [
  {
    json: profile
  }
];
